import runpy
from pathlib import Path
runpy.run_path(str(Path(__file__).with_name('runtime.py')))
import hashlib
import json
import uuid
import nbformat
from pgm_setup import get_pep_setup
root=Path.cwd()
scope={'get_pep_setup':get_pep_setup}
cells=(root/'supplementary/b2_cells.py').read_text(encoding='utf-8-sig')
exec(compile(cells,'b2_cells','exec'),scope)
b1=scope['b1']
selected=scope['selected']
allowlist=json.loads((root/'supplementary/approved/allowlist.json').read_text())
paths=[root/'pgm_setup.py',root/'supplementary/certificate.py']+[Path(p) for p in allowlist['exact_read_files'] if '/pepflow/' in p.replace('\\','/') and p.endswith('.py')]
hashes={str(p.relative_to(root)).replace('\\','/'):hashlib.sha256(p.read_bytes()).hexdigest() for p in paths}
state={**b1,**selected,'N_verify':selected['N'],'tau_sol':selected['named_dual_values']['initial_condition'],'tau_name':'initial_condition','normalization':{'tau_name':'initial_condition','initial_condition':b1['initial_condition'],'performance_metric':b1['performance_metric'],'bound_value':selected['opt_value'],'bound_formula':b1['conjectured_rate']},'certificate_provenance':{'solve_id':str(uuid.uuid4()),'pep_type':'primal','solver_status':selected['solver_status'],'source_hashes':hashes,'solver':{'api':'CVXPrimalSolver.build_problem','effective_name':'CLARABEL','settings':{}}},'numerical_checks':{'tolerances':{'identity_atol':1e-5,'identity_rtol':0,'reconstruction_atol':1e-4,'reconstruction_rtol':1e-5,'dual_tol':1e-6,'psd_tol':1e-6,'dense_opt_atol':1e-5},'residuals':scope['residuals'],'passed':True},'numerical_decomposition':{'method':'direct','factorization':'spectral; all eigenvalues retained','D':scope['D'].tolist(),'ell_coords':scope['E'].tolist(),'basis_labels':selected['basis_vectors']},'closed_form_search':{'completed':True,'references_reviewed':['Own sparse solve; no pre-existing target sources permitted'],'attempts':[{'method':'Rational approximations and cumulative forward weights','outcome':'candidate formulas for both f and g groups','max_error':scope['err']},{'method':'Construct candidate S by complete weighted identity; compare Gram, function, offset coordinates','outcome':'candidate; global PSD unresolved','max_error':scope['candidate_error']}],'unresolved_components':['all-horizon S PSD and certificate identity proof']},'formula_status':{'lambda':'candidate','S':'candidate'},'lamb_code':cells[cells.index('def candidate_multiplier'):cells.index('candidate_values=')],'S_code':'S_candidate = -pb.performance_metric + sp.Rational(1,4*N) + sum((candidate_multiplier(c.name,N)*(c.lhs-c.rhs) for c in entries),pf.Scalar.zero())','S_decomp_type':'direct','numerical_certificate_verified':True,'analytic_full_pep_verified':False,'lyapunov_proof_verified':False,'require_analytic_full_pep':False,'proof_valid':True}
keys=('N_verify','params_json','relaxed_constraints','S_matrix','S_row_names','S_col_names','basis_vectors','basis_scalars','opt_value','tau_sol','tau_name','named_dual_values','constraint_metadata','normalization','certificate_provenance','numerical_checks','numerical_decomposition')
state['certificate_id']=hashlib.sha256(json.dumps({k:state[k] for k in keys},sort_keys=True,separators=(',',':'),allow_nan=False).encode()).hexdigest()
for filename in ('pgm_b2.json','pgm_relaxed.json'):
    (root/'state'/filename).write_text(json.dumps(state,indent=2,allow_nan=False))
book=nbformat.read(root/'pgm_example_lyap.ipynb',as_version=4)
book.cells[8:9]=[nbformat.v4.new_markdown_cell(r'''## B2 full numerical certificate and initial formula search
The dense solve uses all smooth-convex and convex interpolation inequalities. The sparse solve retains minimizer-to-iterate and forward consecutive pairs for each function. All selected multipliers, the bound, and the Gram remainder come from one primal solve. The complete identity is
$$h(x_N)-h(x_\star)-\tau-\sum_c d_c R_c+S=0.$$
Here $R_c\le0$ includes the initial squared-distance constraint. The normalized sample is $L=R=1$, $N=4$.
The following code reconstructs the context and every scalar constraint, verifies the saved numerical certificate, and tests initial candidate formulas. Spectral factors retain every eigenvalue and reconstruct this same selected $S$.
Candidate forward multipliers are $a_i=(i+1)/(2N-i)$ for $f$ and $b_i=i/(2N-i)$ for $g$. Star weights are consecutive differences, with terminal cumulative weight one. The candidate $S$ is generated by the weighted identity; its global PSD proof is unresolved. These are numerical candidates, not an analytic proof.
'''),nbformat.v4.new_code_cell(cells)]
nbformat.write(book,root/'pgm_example_lyap.ipynb')
print('B2 state and notebook saved.')
